def leg(geom,param,mass):
    effective=param['range_empty']+(param['range_full']-param['range_empty'])*mass/param['capacity']
    e=param['battery']*geom['d']/effective+(param['empty']+mass)*G*geom['up']/(param['efficiency']*3.6e6)
    t=geom['d']/param['speed']+geom['up']/param['climb']+geom['down']/param['descend']
    return float(e),float(t)


def trip(zone_boxes, param, terrain, boxmap):
    """zone_boxes为[(服务区,[箱号]),...]，返回耗能/时长/逐区交付相对时刻/段时序。"""
    allids=[bid for _,ids in zone_boxes for bid in ids]
    mass=sum(boxmap[b]['m'] for b in allids)
    volume=sum(boxmap[b]['v'] for b in allids)
    if mass>param['capacity']+1e-8 or volume>param['volume']+1e-8:return None
    t=param['prep']+len(allids)*param['load'];e=0;cur='O01';delivery={};segs=[]
    for dest,ids in list(zone_boxes)+[('O01',[])]:
        geo=terrain.link(cur,dest);de,dt=leg(geo,param,mass)
        segs.append(dict(start=t,end=t+dt,geom=geo,mass=mass));t+=dt;e+=de
        if dest!='O01':
            t+=param['handoff']+param['unload']*len(ids)
            delivery.update({b:t for b in ids})
            mass-=sum(boxmap[b]['m'] for b in ids)
        cur=dest
    if e>param['battery']*(1-param['reserve'])+1e-8:return None
    return dict(energy=e,duration=t,delivery=delivery,segments=segs,mass=sum(boxmap[b]['m'] for b in allids),volume=volume)


